const E_ = { agent: ['Production AI Agent Platform', '../case-production-ai-agent-platform.html'], eval: ['LLM Evaluation Framework', '../case-llm-eval-framework.html'], weir: ['MCP Weir governance', '../case-mcp-weir.html'], rag: ['GenAI Document Assistant', '../case-genai-doc-assistant.html'], copilot: ['Support Escalation Copilot', '../case-support-escalation-copilot.html'], lab: ['NASHA AI Lab architecture', '../case-nasha-ai-lab-architecture.html'] };
