  $('#notif').innerHTML = `<h2 style="font-size:1rem">Alerts</h2><ul>${k.pendingApprovals ? `<li><a href="#/governance">${k.pendingApprovals} approvals pending</a></li>` : ''}${E.inventoryView(state).filter(i => i.low).map(i => `<li><a href="#/inventory">Low stock: ${esc(i.name)}</a></li>`).join('')}${n ? '' : '<li class="muted">Nothing needs attention.</li>'}</ul>`;
