  if (a === 'fulfil') act({ type: 'ORDER_FULFIL', orderId: id }); else if (a === 'cancel') act({ type: 'ORDER_CANCEL', orderId: id }); else if (a === 'paid') act({ type: 'ORDER_MARK_PAID', orderId: id });
  else if (a === 'clear') { ui.cart.lines = {}; render(); } else if (a === 'replay') { const r = act(ui.last); if (r.ok && r.result.duplicate) toast('Duplicate submission recognised: no second order was created.'); }
  else if (a === 'agent') { const r = act({ type: 'AGENT_RUN', agentId: id }); if (r.ok) { agentOut(r.result); render(); live('Agent run complete: rule-based demo'); } }
  else if (a === 'receive') act({ type: 'PURCHASE_RECEIVE', purchaseId: id }); else if (a === 'approve' || a === 'reject') { const n = $('#n-' + id); decide(id, a === 'approve' ? 'APPROVE' : 'REJECT', n ? n.value : ''); }
  else if (a === 'onboard') act({ type: 'ONBOARD_START', employeeId: id }); else if (a === 'task') act({ type: 'ONBOARD_TASK', employeeId: id, taskId: b.dataset.task });
  else if (a === 'tstatus') act({ type: 'TICKET_UPDATE', ticketId: id, status: b.dataset.status }); else if (a === 'tesc') act({ type: 'TICKET_ESCALATE', ticketId: id }); else if (a === 'tcredit') act({ type: 'TICKET_PROPOSE_CREDIT', ticketId: id, amountCents: 1500 });
  else if (a === 'funnel') { ui.mkt.sel = id; render(); } else if (a === 'infra') { ui.infra = id; render(); }
  else if (a === 'verify') { const v = E.verifyAudit(state); ui.verify = v.ok ? `Audit hash chain verified: ${v.events} events, each linked to the previous by SHA-256.` : `Audit chain BROKEN at event ${v.brokenAt}.`; render(); }
  else if (a === 'consistency') { const c = E.consistency(state); ui.verify = c.ok ? 'Consistency check passed: ledger equals live orders, no negative stock, audit chain intact.' : 'Inconsistent: ' + c.issues.join('; '); render(); }
  else if (a === 'tamper') { const t = JSON.parse(JSON.stringify(state)); if (t.audit.length > 2) t.audit[1].detail = 'edited'; const v = E.verifyAudit(t); ui.verify = `Tamper test on a copy: editing event 2 ${v.ok ? 'was NOT detected' : 'was detected at event ' + v.brokenAt}. Your real state was not touched.`; render(); }
  else if (a === 'moreaudit') { ui.audit.n += 30; render(); } else if (a === 'reset') resetDemo();
