document.addEventListener('input', e => { const q = e.target.closest('[data-qty]'); if (q) { let v = parseInt(q.value, 10); ui.cart.lines[q.dataset.qty] = Number.isInteger(v) ? v : 0; const t = Object.entries(ui.cart.lines).reduce((a, [id, n]) => a + (n > 0 ? prod(id).priceCents * n : 0), 0); $('#total').textContent = usd(t); } });
document.addEventListener('change', e => { if (e.target.id === 'cust') ui.cart.customerId = e.target.value; if (e.target.dataset.mkt) { ui.mkt[e.target.dataset.mkt] = e.target.value; render(); } });
