function guideNext() {
  if (ui.guide >= GUIDE.length) return false;
  if (ui.guide > 0 && !ui.gs) ui.gs = snap();
  const r = GUIDE[ui.guide].run();
  if (r && r.ok !== false) { ui.guideLog.push(GUIDE[ui.guide].facts()); ui.guide++; } else { toast('This step could not run in the current state. Choose Reset and start over.', true); ui.play = false; }
  $('#role').value = ui.role; render(); return !!(r && r.ok !== false);
}
function guidePlay() {
  if (ui.play) { ui.play = false; clearTimeout(ui.timer); render(); return; }
  if (ui.guide >= GUIDE.length) return;
  ui.play = true;
  const tick = () => { if (!ui.play || route().m !== 'guide') { ui.play = false; return; } const good = guideNext(); if (good && ui.guide < GUIDE.length) ui.timer = setTimeout(tick, 8000); else { ui.play = false; render(); } };
  tick();
}

